@@ -1,3 +1,3 @@
 @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Marcellus+SC&display=swap');
 :root{--ink:#17232a;--gold:#e4b954;--cream:#f4ecd8;--panel:rgba(22,31,34,.94);--muted:#a9b0a5;--red:#d96855}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#1a2829;color:var(--cream);font-family:'DM Sans',sans-serif;touch-action:none;user-select:none;-webkit-user-select:none}button{font:inherit;color:inherit;border:0;cursor:pointer;touch-action:manipulation}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#899a64}#game{display:block;width:100%;height:100%;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,16,19,.42),transparent 25%,transparent 62%,rgba(8,16,19,.36))}.topbar{position:absolute;z-index:2;top:max(14px,env(safe-area-inset-top));left:50%;transform:translateX(-50%);width:min(940px,calc(100% - 32px));height:58px;display:flex;align-items:center;gap:12px;padding:8px 12px;border:1px solid rgba(241,223,174,.22);border-radius:11px;background:linear-gradient(180deg,rgba(28,38,38,.96),rgba(17,26,28,.94));box-shadow:0 6px 24px #17202055}.brand{display:flex;align-items:center;gap:9px;margin-right:auto;min-width:170px}.brand-mark{font-size:27px;color:var(--gold);text-shadow:0 0 15px #e4b95466}.brand b{display:block;font:15px 'Marcellus SC',serif;letter-spacing:2px}.brand small{display:block;font-size:8px;letter-spacing:3px;color:#aab1a1;margin-top:1px}.stat-pill{height:38px;min-width:92px;border-radius:7px;background:#0f1719;border:1px solid #ffffff12;display:grid;grid-template-columns:22px auto;grid-template-rows:20px 10px;align-items:center;padding:3px 9px}.stat-pill>span{grid-row:1/3;font-size:19px;color:var(--gold)}.stat-pill .people{color:#d9e3ca}.stat-pill b{font-size:13px;line-height:16px}.stat-pill small{font-size:7px;letter-spacing:1.6px;color:#939f93;line-height:9px}.icon-btn{width:37px;height:37px;border-radius:7px;background:#35403c;color:#e8d8ae;font-size:16px}.objective{position:absolute;z-index:1;top:88px;left:50%;transform:translateX(-50%);background:rgba(25,34,32,.78);border:1px solid #e8ddb83b;border-radius:20px;padding:7px 14px;display:flex;align-items:center;gap:8px;font-size:11px;letter-spacing:.3px;white-space:nowrap}.target-dot{width:7px;height:7px;background:#ec7960;border-radius:50%;box-shadow:0 0 9px #eb695d}.orders{position:absolute;left:18px;top:50%;transform:translateY(-50%);display:flex;flex-direction:column;gap:8px}.order-btn{width:82px;height:72px;border:1px solid #e8ddb83b;border-radius:9px;background:rgba(22,31,30,.86);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:1px;box-shadow:0 4px 15px #17202045}.order-btn>span{font-size:19px;color:#dac080}.order-btn b{font-size:9px;letter-spacing:1.2px}.order-btn small{font-size:8px;color:#aab2a6}.order-btn.active{border-color:#e3ba5f;background:rgba(77,65,41,.93);box-shadow:0 0 18px #deb85c32}.minimap-frame{position:absolute;right:18px;top:91px;width:180px;height:126px;padding:5px;border:1px solid #e7dcb24c;border-radius:8px;background:rgba(22,31,30,.9);box-shadow:0 5px 16px #17202055}.minimap-frame canvas{display:block;width:100%;height:calc(100% - 14px);border-radius:4px}.map-label{display:block;text-align:center;font-size:7px;letter-spacing:2px;color:#bbc1aa;line-height:12px}.army-panel{position:absolute;z-index:2;bottom:max(15px,env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);width:min(490px,calc(100% - 24px));padding:12px 14px 8px;border:1px solid #e8ddb83b;border-radius:11px;background:var(--panel);box-shadow:0 8px 28px #17202066}.panel-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:9px}.panel-heading b{display:block;font:14px 'Marcellus SC',serif;letter-spacing:.5px}.eyebrow{display:block;font-size:8px;letter-spacing:1.8px;color:#c5a75f;margin-bottom:3px}.panel-heading>span{font-size:10px;color:#acb5a7}.unit-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.unit-card{min-height:75px;border:1px solid #f1e7c51c